#!/bin/sh
# Xcode Cloud runs this after cloning. The .xcodeproj is generated by XcodeGen
# and git-ignored, so generate it here before Xcode Cloud resolves and builds.
set -eu

cd "$CI_PRIMARY_REPOSITORY_PATH"

# The team ID is never committed; set HALFUNIT_TEAM_ID in the workflow's
# environment variables.
if [ -n "${HALFUNIT_TEAM_ID:-}" ]; then
    printf 'DEVELOPMENT_TEAM = %s\n' "$HALFUNIT_TEAM_ID" > Config/Local.xcconfig
else
    echo "warning: HALFUNIT_TEAM_ID is not set; signing uses the project defaults."
fi

export HOMEBREW_NO_AUTO_UPDATE=1
export HOMEBREW_NO_INSTALL_CLEANUP=1
./scripts/bootstrap.sh
